//! SQLite 连接、建表与种子数据。
//!
//! 表结构对齐 Java 版 MySQL 迁移（`afv_*` / `sys_*`），列名保持一致，
//! 由 MySQL 迁移脚本机械转换而来：`bigint` → `INTEGER`、`json`/`text` → `TEXT`、`datetime` → `TEXT`。
//! 每张表的列与真实 Java 版完全一致，避免手写漂移。

use sqlx::sqlite::{SqliteConnectOptions, SqlitePoolOptions};
use sqlx::{Pool, Sqlite};
use std::str::FromStr;

use crate::error::{AppError, AppResult};
use crate::paths::AppPaths;

pub type Db = Pool<Sqlite>;

pub async fn connect(paths: &AppPaths) -> AppResult<Db> {
    let url = format!("sqlite://{}", paths.db_file.display());
    let options = SqliteConnectOptions::from_str(&url)
        .map_err(|e| AppError::internal(format!("SQLite 连接串无效: {e}")))?
        .create_if_missing(true)
        .journal_mode(sqlx::sqlite::SqliteJournalMode::Wal)
        .synchronous(sqlx::sqlite::SqliteSynchronous::Normal)
        .foreign_keys(true)
        .busy_timeout(std::time::Duration::from_secs(10));

    let pool = SqlitePoolOptions::new()
        .max_connections(8)
        .connect_with(options)
        .await?;

    migrate(&pool).await?;
    Ok(pool)
}

async fn migrate(db: &Db) -> AppResult<()> {
    for statement in SCHEMA {
        sqlx::query(statement).execute(db).await.map_err(|e| {
            AppError::internal(format!("建表失败: {e}\nSQL: {}", &statement[..statement.len().min(120)]))
        })?;
    }
    Ok(())
}

